// The episode-titles routing tests (episode-titles 2.1/2.2): a SERIES run's
// ConvertResult.EpisodeTitles are routed onto the series' episode documents
// under their own leases (D5), and an explicit series-row strip cascades to
// those episode documents (D6). The fixtures reuse the serials two-level
// series_queue_test.go fakes: the episode docs carry their parse facts
// (sources.serial-parser season+episode — the already-parsed state), and the
// routed namespace is the shikimori stand-in's side-output.

// routedSeriesDoc is a parsed directory series with its season fact already in
// the parse namespace (the pre-title state the series run enriches).
func routedSeriesDoc(season int64) map[string]any {
	doc := serialDoc("Show.Name.S01")
	doc["sources"] = map[string]any{
		"serial-parser": map[string]any{"title": "Show Name", "season": float64(season)},
	}
	return doc
}

// routedEpisodeDoc is a parsed episode document carrying its (season, episode)
// parse facts — the namespace-agnostic pair the routing matches on.
func routedEpisodeDoc(ep, season int64) map[string]any {
	rel := episodeRel(ep)
	doc := episodeDoc("Show.Name.S01", rel)
	doc["sources"] = map[string]any{
		"serial-parser": map[string]any{"season": float64(season), "episode": float64(ep)},
	}
	return doc
}

// episodeRel is the depth-1 episode path inside the fixture series directory.
func episodeRel(ep int64) string {
	return fmt.Sprintf("Show.Name.S01/Show.Name.S01E%02d.mkv", ep)
}

// putRoutedEpisode upserts an EPISODE item carrying its relative_path (the
// column QueryItemsBySeries matches — the routing's and the cascade's backing
// read; the series_queue_test.go fixture helper leaves it unset because
// derivation never reads it) and returns its row id.
func putRoutedEpisode(t *testing.T, s *store.Store, libID int64, rel, status string, doc map[string]any) string {
	t.Helper()
	docBytes, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal episode doc: %v", err)
	}
	it := store.Item{
		ID: "itm_" + strconv.FormatInt(libID, 10) + "_" + rel, ModuleID: "serial",
		LibraryID: libID, FileID: rel, RelativePath: rel, MediaType: "serial",
		Document: docBytes, Status: status,
	}
	if err := s.PutItem(context.Background(), it); err != nil {
		t.Fatalf("PutItem %s: %v", rel, err)
	}
	return it.ID
}

// epTitle is one ConvertResult.EpisodeTitle entry: the source's episode number
// and that episode's namespace fields.
func epTitle(ep int64, title string) *metadatav1.EpisodeTitle {
	st, err := structpb.NewStruct(map[string]any{"title": title})
	if err != nil {
		panic(err) // a fixed string-keyed map never fails
	}
	return &metadatav1.EpisodeTitle{Episode: ep, Metadata: st}
}

// titleRun is one successful series-run source result carrying entries, the
// shape driveSources hands the router: the plugin id the routed namespace is
// written under, plus the run's hints and confidence for the stamps.
func titleRun(pluginID string, entries []*metadatav1.EpisodeTitle) sourceResult {
	return sourceResult{
		pluginID:      pluginID,
		episodeTitles: entries,
		provHints: map[string]*commonv1.Provenance{
			"title": {PluginVersion: "v1.0.0", Confidence: 0.9},
		},
		matchConfidence: 0.42,
	}
}

// titlesFake is the shikimori stand-in: it applies ONLY to serial records (an
// episode document still never matches at Match — the routing must be the only
// writer of episode titles) and converts to a series namespace plus two
// episode-title entries with per-field provenance hints.
func titlesFake() *fnSource {
	return &fnSource{
		id: "shikimori",
		match: func(req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
			if !req.GetItem().GetParsed().GetFields()["serial_record"].GetBoolValue() {
				return &metadatav1.MatchResult{Applies: false, Reason: "episode documents never match"}, nil
			}
			return &metadatav1.MatchResult{Applies: true, Confidence: 0.42}, nil
		},
		convert: func(*metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
			st, _ := structpb.NewStruct(map[string]any{"title": "Show Name"})
			return &metadatav1.ConvertResult{
				Metadata: st,
				EpisodeTitles: []*metadatav1.EpisodeTitle{
					epTitle(1, "Episode One"),
					epTitle(2, "Episode Two"),
				},
				Provenance: map[string]*commonv1.Provenance{
					"title": {PluginVersion: "v1.0.0", Confidence: 0.9},
				},
			}, nil
		},
	}
}

// docOf decodes a row's current persisted document.
func docOf(t *testing.T, s *store.Store, id string) map[string]any {
	t.Helper()
	return decodeDoc(rowDocument(t, s, id))
}

// TestEpisodeTitleRouting is the routing contract (episode-titles 2.1, D5):
// matched episode documents gain the routed namespace with their stamps under
// their own lease; the season/number guard leaves mismatches untouched; empty
// runs and file-backed series are no-ops; a held lease defers and retries
// once, and a row that stays held keeps its bytes.
func TestEpisodeTitleRouting(t *testing.T) {
	ctx := context.Background()
	entries := []*metadatav1.EpisodeTitle{epTitle(1, "Episode One"), epTitle(2, "Episode Two")}

	t.Run("matched episodes gain the routed namespace with stamps", func(t *testing.T) {
		s, reg := queueTestStore(t)
		seriesID := putSeriesRow(t, s, "serial", 1, "Show.Name.S01", statusReady, routedSeriesDoc(1))
		ep1 := putRoutedEpisode(t, s, 1, episodeRel(1), statusReady, routedEpisodeDoc(1, 1))
		ep2 := putRoutedEpisode(t, s, 1, episodeRel(2), statusReady, routedEpisodeDoc(2, 1))
		seriesBytes := rowDocument(t, s, seriesID)

		sr, err := s.GetSeries(ctx, seriesID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
		q.routeEpisodeTitles(ctx, sr, decodeDoc(sr.Document), []sourceResult{titleRun("shikimori", entries)})

		for ep, tc := range map[int]struct {
			id   string
			want string
		}{1: {ep1, "Episode One"}, 2: {ep2, "Episode Two"}} {
			itemID := tc.id
			doc := docOf(t, s, itemID)
			sources, _ := doc["sources"].(map[string]any)
			ns, ok := sources["shikimori"].(map[string]any)
			if !ok {
				t.Fatalf("ep %d: sources.shikimori missing after routing: %v", ep, sources)
			}
			if len(ns) != 1 || ns["title"] != tc.want {
				t.Fatalf("ep %d: routed namespace = %v, want map[title:%s]", ep, ns, tc.want)
			}
			// The stamps: per-field provenance over the entry fields, the run
			// hints and confidence; the view binding pointing at the value.
			prov, _ := doc["_provenance"].(map[string]any)
			titleProv, _ := prov["title"].(map[string]any)
			if titleProv["plugin_id"] != "shikimori" || titleProv["plugin_version"] != "v1.0.0" {
				t.Fatalf("ep %d: _provenance.title = %v, want the shikimori run hint stamps", ep, titleProv)
			}
			if titleProv["confidence"] != 0.9 {
				t.Fatalf("ep %d: provenance confidence = %v, want the run hint 0.9", ep, titleProv["confidence"])
			}
			if ts, _ := titleProv["fetched_at"].(string); ts == "" {
				t.Fatalf("ep %d: provenance fetched_at missing: %v", ep, titleProv)
			}
			view, _ := doc["_view"].(map[string]any)
			titleView, _ := view["title"].(map[string]any)
			if titleView["value"] != tc.want || titleView["source"] != "shikimori" {
				t.Fatalf("ep %d: _view.title = %v, want the routed value + source", ep, titleView)
			}
			// Routing is not a chain run: no _stages entry, no lifecycle change.
			if stages, _ := doc["_stages"].([]map[string]any); len(stages) != 0 {
				t.Fatalf("ep %d: routing wrote _stages entries: %v", ep, stages)
			}
			it, err := s.GetItem(ctx, itemID)
			if err != nil {
				t.Fatalf("GetItem ep %d: %v", ep, err)
			}
			if it.Status != statusReady {
				t.Fatalf("ep %d: status = %q, want untouched ready", ep, it.Status)
			}
		}
		// The series row itself is untouched by the routing of its side-output.
		if after := rowDocument(t, s, seriesID); !bytes.Equal(seriesBytes, after) {
			t.Fatalf("series document changed during routing:\n%s\n%s", seriesBytes, after)
		}
	})

	t.Run("season or number mismatch leaves the document untouched", func(t *testing.T) {
		s, reg := queueTestStore(t)
		seriesID := putSeriesRow(t, s, "serial", 1, "Show.Name.S01", statusReady, routedSeriesDoc(1))
		otherSeason := putRoutedEpisode(t, s, 1, episodeRel(1), statusReady, routedEpisodeDoc(1, 2)) // season 2
		otherNumber := putRoutedEpisode(t, s, 1, episodeRel(9), statusReady, routedEpisodeDoc(9, 1)) // no entry 9
		before := map[string][]byte{
			otherSeason: rowDocument(t, s, otherSeason),
			otherNumber: rowDocument(t, s, otherNumber),
		}

		sr, err := s.GetSeries(ctx, seriesID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
		q.routeEpisodeTitles(ctx, sr, decodeDoc(sr.Document), []sourceResult{titleRun("shikimori", entries)})

		for id, want := range before {
			if got := rowDocument(t, s, id); !bytes.Equal(want, got) {
				t.Fatalf("episode %s was touched by a mismatched route:\n%s\n%s", id, want, got)
			}
		}
	})

	t.Run("no entries is a no-op", func(t *testing.T) {
		s, reg := queueTestStore(t)
		seriesID := putSeriesRow(t, s, "serial", 1, "Show.Name.S01", statusReady, routedSeriesDoc(1))
		ep1 := putRoutedEpisode(t, s, 1, episodeRel(1), statusReady, routedEpisodeDoc(1, 1))
		before := rowDocument(t, s, ep1)

		sr, err := s.GetSeries(ctx, seriesID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
		q.routeEpisodeTitles(ctx, sr, decodeDoc(sr.Document), []sourceResult{titleRun("shikimori", nil)})
		q.routeEpisodeTitles(ctx, sr, decodeDoc(sr.Document), nil) // no runs at all

		if got := rowDocument(t, s, ep1); !bytes.Equal(before, got) {
			t.Fatalf("entryless run routed a write:\n%s\n%s", before, got)
		}
	})

	t.Run("file-backed series is a no-op", func(t *testing.T) {
		s, reg := queueTestStore(t)
		doc := routedSeriesDoc(1)
		doc["parsed"].(map[string]any)["backing"] = store.SeriesBackingFile // a stray top-level video
		seriesID := putSeriesRow(t, s, "serial", 1, "Stray.Show.S01", statusReady, doc)
		ep1 := putRoutedEpisode(t, s, 1, episodeRel(1), statusReady, routedEpisodeDoc(1, 1)) // even matching facts
		before := rowDocument(t, s, ep1)

		sr, err := s.GetSeries(ctx, seriesID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
		q.routeEpisodeTitles(ctx, sr, decodeDoc(sr.Document), []sourceResult{titleRun("shikimori", entries)})

		if got := rowDocument(t, s, ep1); !bytes.Equal(before, got) {
			t.Fatalf("file-backed series routed a write:\n%s\n%s", before, got)
		}
	})

	t.Run("held lease defers and the one retry lands after expiry", func(t *testing.T) {
		s, reg := queueTestStore(t)
		seriesID := putSeriesRow(t, s, "serial", 1, "Show.Name.S01", statusReady, routedSeriesDoc(1))
		ep1 := putRoutedEpisode(t, s, 1, episodeRel(1), statusReady, routedEpisodeDoc(1, 1))

		sr, err := s.GetSeries(ctx, seriesID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
		// An in-flight episode worker owns the row; its TTL expires within the
		// routing's one bounded retry delay, so the retry pass lands the write.
		if !q.leases.acquire(ep1, "worker", 5*time.Millisecond) {
			t.Fatal("could not seed the held lease")
		}
		q.routeEpisodeTitles(ctx, sr, decodeDoc(sr.Document), []sourceResult{titleRun("shikimori", entries)})

		doc := docOf(t, s, ep1)
		sources, _ := doc["sources"].(map[string]any)
		if sources["shikimori"] == nil {
			t.Fatalf("retry pass never landed the held row's title: %v", sources)
		}
	})

	t.Run("lease held past the retry keeps the document byte-identical", func(t *testing.T) {
		s, reg := queueTestStore(t)
		seriesID := putSeriesRow(t, s, "serial", 1, "Show.Name.S01", statusReady, routedSeriesDoc(1))
		ep1 := putRoutedEpisode(t, s, 1, episodeRel(1), statusReady, routedEpisodeDoc(1, 1))
		before := rowDocument(t, s, ep1)

		sr, err := s.GetSeries(ctx, seriesID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
		if !q.leases.acquire(ep1, "worker", time.Hour) {
			t.Fatal("could not seed the held lease")
		}
		defer q.leases.release(ep1)
		q.routeEpisodeTitles(ctx, sr, decodeDoc(sr.Document), []sourceResult{titleRun("shikimori", entries)})

		if got := rowDocument(t, s, ep1); !bytes.Equal(before, got) {
			t.Fatalf("a row that stayed held was written:\n%s\n%s", before, got)
		}
	})

	t.Run("worker routes a series run titles onto its episodes", func(t *testing.T) {
		s, reg := queueTestStore(t)
		seriesID := putSeriesRow(t, s, "serial", 1, "Show.Name.S01", "pending", routedSeriesDoc(1))
		ep1 := putRoutedEpisode(t, s, 1, episodeRel(1), statusPending, routedEpisodeDoc(1, 1))
		ep2 := putRoutedEpisode(t, s, 1, episodeRel(2), statusPending, routedEpisodeDoc(2, 1))
		otherSeason := putRoutedEpisode(t, s, 1,
			"Show.Name.S01/Show.Name.S02E01.mkv", statusPending, routedEpisodeDoc(1, 2))

		q := NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())
		q.resolve = serialResolver(map[string]sdk.MetadataSource{
			"shikimori":     titlesFake(), // episode documents never match at Match
			"frame-grabber": grabberFake(),
		})
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		q.Notify(ctx, 1)
		waitForSeriesStatus(t, s, seriesID, statusReady, 3*time.Second)

		// The routing runs inside the series' own worker turn, after the run's
		// namespace is persisted — poll until the side-output lands.
		waitForRoutedTitle(t, s, ep1)
		waitForRoutedTitle(t, s, ep2)

		for ep, tc := range map[int]struct {
			id   string
			want string
		}{1: {ep1, "Episode One"}, 2: {ep2, "Episode Two"}} {
			itemID := tc.id
			doc := docOf(t, s, itemID)
			sources, _ := doc["sources"].(map[string]any)
			ns, _ := sources["shikimori"].(map[string]any)
			if ns["title"] != tc.want {
				t.Fatalf("ep %d: routed title = %v, want the entry title", ep, ns["title"])
			}
			view, _ := doc["_view"].(map[string]any)
			titleView, _ := view["title"].(map[string]any)
			if titleView["source"] != "shikimori" {
				t.Fatalf("ep %d: _view.title = %v, want the shikimori stamp", ep, titleView)
			}
			it, err := s.GetItem(ctx, itemID)
			if err != nil {
				t.Fatalf("GetItem ep %d: %v", ep, err)
			}
			if it.Status != statusPending {
				t.Fatalf("ep %d: status = %q, want untouched pending", ep, it.Status)
			}
		}
		// The season guard on the real graph: another season's episode in the
		// same directory stays titleless, its parse facts intact.
		other := docOf(t, s, otherSeason)
		sources, _ := other["sources"].(map[string]any)
		if sources["shikimori"] != nil {
			t.Fatalf("another season's episode was routed a title: %v", sources)
		}
		if sources["serial-parser"] == nil {
			t.Fatalf("another season's episode lost its parse facts: %v", sources)
		}
		// The series run result is exactly the chain's own contribution.
		sr := waitForSeriesStatus(t, s, seriesID, statusReady, 3*time.Second)
		seriesDoc := decodeDoc(sr.Document)
		seriesSources, _ := seriesDoc["sources"].(map[string]any)
		if seriesSources["serial-parser"] == nil {
			t.Fatalf("series lost its parse namespace: %v", seriesSources)
		}
		runNS, ok := seriesSources["shikimori"].(map[string]any)
		if !ok || runNS["title"] != "Show Name" {
			t.Fatalf("series run namespace = %v, want the chain's own write", seriesSources["shikimori"])
		}
	})
}

// waitForRoutedTitle polls the episode document until the routed namespace
// lands (the routing runs inside the series worker's turn, after the series
// status is already visible ready).
func waitForRoutedTitle(t *testing.T, s *store.Store, itemID string) map[string]any {
	t.Helper()
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		doc := docOf(t, s, itemID)
		if sources, _ := doc["sources"].(map[string]any); sources["shikimori"] != nil {
			return doc
		}
		time.Sleep(time.Millisecond)
	}
	t.Fatalf("episode %s never received its routed title (timeout)", itemID)
	return nil
}

// TestReenrichSourceSeriesCascade is the strip-cascade contract (episode-titles
// 2.2, D6): an explicit series-row strip scopes that series' episode items too
// — the routed side-output refreshes with its series — while a non-episode
// item, another series' rows, and every other plugin namespace stay intact.
// An item-only explicit scope stays exactly as before.
func TestReenrichSourceSeriesCascade(t *testing.T) {
	ctx := context.Background()

	// cascadeFixture seeds: the fixture series (shikimori + parse namespaces,
	// shikimori identifiers) with one routed episode; an unrelated top-level
	// item carrying shikimori; and a SECOND series with its own routed episode.
	cascadeFixture := func(t *testing.T) (s *store.Store, q *Queue, seriesID, epID, movieID, otherSeriesID, otherEpID string) {
		t.Helper()
		s, reg := queueTestStore(t)
		q = NewQueue(Deps{Store: s, Modules: reg}, fastQueueCfg())

		seriesDoc := routedSeriesDoc(1)
		seriesDoc["sources"].(map[string]any)["shikimori"] = map[string]any{"title": "Old Show"}
		seriesDoc["identifiers"] = map[string]any{"shikimori_id": "123"}
		seriesDoc["_provenance"] = map[string]any{
			"title":  map[string]any{"plugin_id": "shikimori"},
			"season": map[string]any{"plugin_id": "serial-parser"},
		}
		seriesDoc["_view"] = map[string]any{
			"title": map[string]any{"value": "Old Show", "source": "shikimori"},
		}
		seriesID = putSeriesRow(t, s, "serial", 1, "Show.Name.S01", "ready", seriesDoc)

		epDoc := routedEpisodeDoc(1, 1)
		epDoc["sources"].(map[string]any)["shikimori"] = map[string]any{"title": "Old Episode One"}
		epDoc["_provenance"] = map[string]any{
			"title":  map[string]any{"plugin_id": "shikimori"},
			"season": map[string]any{"plugin_id": "serial-parser"},
		}
		epDoc["_view"] = map[string]any{
			"title": map[string]any{"value": "Old Episode One", "source": "shikimori"},
		}
		epID = putRoutedEpisode(t, s, 1, episodeRel(1), "ready", epDoc)

		movieDoc := map[string]any{
			"parsed":  map[string]any{"relative_path": "Movie.2020.mkv"},
			"sources": map[string]any{"shikimori": map[string]any{"title": "Movie"}},
		}
		movieID = putRoutedEpisode(t, s, 1, "Movie.2020.mkv", statusReady, movieDoc)

		otherDoc := routedSeriesDoc(1)
		otherDoc["sources"].(map[string]any)["shikimori"] = map[string]any{"title": "Other Show"}
		otherSeriesID = putSeriesRow(t, s, "serial", 1, "Other.Show.S01", statusReady, otherDoc)
		otherEpDoc := routedEpisodeDoc(1, 1)
		otherEpDoc["sources"].(map[string]any)["shikimori"] = map[string]any{"title": "Other Episode One"}
		otherEpID = putRoutedEpisode(t, s, 1, "Other.Show.S01/Other.Show.S01E01.mkv", statusReady, otherEpDoc)
		return s, q, seriesID, epID, movieID, otherSeriesID, otherEpID
	}

	t.Run("explicit series strip cascades to its episode items", func(t *testing.T) {
		s, q, seriesID, epID, movieID, otherSeriesID, otherEpID := cascadeFixture(t)

		stripped, deferred, err := q.ReenrichSource(ctx, 1, "shikimori", seriesID)
		if err != nil {
			t.Fatalf("ReenrichSource: %v", err)
		}
		if stripped != 2 || deferred != 0 {
			t.Fatalf("stripped = %d, deferred = %d, want 2 series+episode stripped, 0 deferred", stripped, deferred)
		}

		// The series: shikimori purged (namespace + provenance + view); the
		// parse namespace and the identity anchor untouched.
		series := docOf(t, s, seriesID)
		seriesSources, _ := series["sources"].(map[string]any)
		if seriesSources["shikimori"] != nil {
			t.Fatalf("series kept its shikimori namespace: %v", seriesSources)
		}
		if seriesSources["serial-parser"] == nil {
			t.Fatalf("series lost its parse namespace: %v", seriesSources)
		}
		ids, _ := series["identifiers"].(map[string]any)
		if ids["shikimori_id"] != "123" {
			t.Fatalf("series identifiers touched by the strip: %v", ids)
		}
		seriesProv, _ := series["_provenance"].(map[string]any)
		if seriesProv["title"] != nil {
			t.Fatalf("series kept the shikimori provenance: %v", seriesProv)
		}
		if seriesProv["season"] == nil {
			t.Fatalf("series lost the parse provenance: %v", seriesProv)
		}
		if sr, _ := s.GetSeries(ctx, seriesID); sr.Status != statusPending {
			t.Fatalf("series status = %q, want the refresh flip to pending", sr.Status)
		}

		// The routed episode: stripped WITH its series; the parse namespace and
		// its provenance stay.
		ep := docOf(t, s, epID)
		epSources, _ := ep["sources"].(map[string]any)
		if epSources["shikimori"] != nil {
			t.Fatalf("episode kept its routed namespace: %v", epSources)
		}
		if epSources["serial-parser"] == nil {
			t.Fatalf("episode lost its parse namespace: %v", epSources)
		}
		epProv, _ := ep["_provenance"].(map[string]any)
		if epProv["title"] != nil {
			t.Fatalf("episode kept the routed provenance: %v", epProv)
		}
		if epProv["season"] == nil {
			t.Fatalf("episode lost the parse provenance: %v", epProv)
		}
		epView, _ := ep["_view"].(map[string]any)
		if epView["title"] != nil {
			t.Fatalf("episode kept the routed view: %v", epView)
		}
		if it, _ := s.GetItem(ctx, epID); it.Status != statusPending {
			t.Fatalf("episode status = %q, want the refresh flip to pending", it.Status)
		}

		// A non-episode item in the same library is NOT in an explicit series scope.
		movie := docOf(t, s, movieID)
		movieSources, _ := movie["sources"].(map[string]any)
		if movieSources["shikimori"] == nil {
			t.Fatalf("unrelated item was stripped by a series-scoped refresh: %v", movieSources)
		}
		if it, _ := s.GetItem(ctx, movieID); it.Status != statusReady {
			t.Fatalf("unrelated item status = %q, want untouched ready", it.Status)
		}

		// Another series and its routed episode stay intact.
		other := docOf(t, s, otherSeriesID)
		if srcs, _ := other["sources"].(map[string]any); srcs["shikimori"] == nil {
			t.Fatalf("other series was stripped: %v", srcs)
		}
		otherEp := docOf(t, s, otherEpID)
		if srcs, _ := otherEp["sources"].(map[string]any); srcs["shikimori"] == nil {
			t.Fatalf("other series' episode was stripped: %v", srcs)
		}
	})

	t.Run("item-only explicit scope stays exactly as before", func(t *testing.T) {
		s, q, seriesID, epID, movieID, _, _ := cascadeFixture(t)

		stripped, deferred, err := q.ReenrichSource(ctx, 1, "shikimori", movieID)
		if err != nil {
			t.Fatalf("ReenrichSource: %v", err)
		}
		if stripped != 1 || deferred != 0 {
			t.Fatalf("stripped = %d, deferred = %d, want exactly the named item", stripped, deferred)
		}
		if srcs, _ := docOf(t, s, movieID)["sources"].(map[string]any); srcs["shikimori"] != nil {
			t.Fatal("the named item kept its namespace")
		}
		// The series and its routed episode are untouched by an item-only scope.
		if srcs, _ := docOf(t, s, seriesID)["sources"].(map[string]any); srcs["shikimori"] == nil {
			t.Fatal("item-only scope cascaded to the series row")
		}
		if srcs, _ := docOf(t, s, epID)["sources"].(map[string]any); srcs["shikimori"] == nil {
			t.Fatal("item-only scope cascaded to the series' episode")
		}
	})
}
